var ROOTS=["nimbus","quanta","lumio","vox","zen","pixo","nova","echo","flux","orbit","data","meta","hyper","neura","cortex","spark","vertex","axon","pulse","drift","halo","cipher","atlas","lumen","strata","nyx","vega","orb","kite","lumo","riddle","sable","tundra","fathom","glint","marrow","pebble","solace","quill","wren"];
var SUF=["ify","ly","hub","stack","labs","ai","io","base","flow","kit","box","loop","sync","verse","mind","forge","bit","wave","grid","works","lytics","works","path","deck","ship","port","node","seed","ware","cast"];
var PRE=["go","re","un","pro","in","over","up","smart","open","micro","super","neo","hyper"];
function rndItem(a,r){ return a[Math.floor((r||Math.random)()*a.length)]; }
function gen(r){
  r=r||Math.random;
  var pat=Math.floor(r()*3);
  var root=rndItem(ROOTS,r), suf=rndItem(SUF,r), pre=rndItem(PRE,r);
  if(pat===0) return root+suf;
  if(pat===1) return pre+root;
  return root+suf.charAt(0).toUpperCase()+suf.slice(1);
}
function batch(n){ var out=[]; for(var i=0;i<n;i++) out.push(gen()); return out; }
var EXPORTS={ ROOTS:ROOTS, SUF:SUF, PRE:PRE, gen:gen, batch:batch };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StartupNameForgePure = EXPORTS; }
